PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE STRING_IDS(id INTEGER PRIMARY KEY, value TEXT);
CREATE TABLE TASK(startNs INTEGER, endNs INTEGER, deviceId INTEGER, connectionId INTEGER, globalTaskId INTEGER, globalPid INTEGER, taskType INTEGER, contextId INTEGER, streamId INTEGER, taskId INTEGER, modelId INTEGER);
CREATE TABLE COMPUTE_TASK_INFO(globalTaskId INTEGER, name INTEGER, opType INTEGER, taskType INTEGER);
CREATE TABLE COMMUNICATION_TASK_INFO(globalTaskId INTEGER, name INTEGER, taskType INTEGER);
CREATE TABLE COMMUNICATION_OP(opName INTEGER, opType INTEGER, startNs INTEGER, endNs INTEGER, connectionId INTEGER, groupName INTEGER, opId INTEGER, deviceId INTEGER);
COMMIT;
